<?php require_once __DIR__.'/bootstrap.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([current_user()['id']]);$orders=$s->fetchAll();page_start('My orders');?><h1>My orders</h1><div class="panel"><table><thead><tr><th>Order</th><th>Total</th><th>Payment</th><th>Fulfilment</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=money($o['subtotal'])?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['fulfilment_status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach ?></tbody></table><?php if(!$orders)echo '<p>No orders yet.</p>';?></div><?php page_end();?>
